class Solution {long long cross(vector<int> a,vector<int> b,vector<int> p){return (1LL*b[0]-a[0])*(1LL*p[1]-a[1])-(1LL*b[1]-a[1])*(1LL*p[0]-a[0]);}public:bool solve(vector<vector<int>> polygon,vector<int> point){bool inside=false;for(int i=0;i<(int)polygon.size();i++){auto a=polygon[i],b=polygon[(i+1)%polygon.size()];if(cross(a,b,point)==0&&point[0]>=min(a[0],b[0])&&point[0]<=max(a[0],b[0])&&point[1]>=min(a[1],b[1])&&point[1]<=max(a[1],b[1]))return true;if((a[1]>point[1])!=(b[1]>point[1])){long long left=(1LL*b[0]-a[0])*(1LL*point[1]-a[1]),right=(1LL*point[0]-a[0])*(1LL*b[1]-a[1]);if(b[1]>a[1]?left>right:left<right)inside=!inside;}}return inside;}};